import json,re
from pathlib import Path
pat=re.compile(r'load|save|iscell|F\.npy|Fneu|fluor|trace|motion|speed|behav|match|output',re.I)
for p in sorted(Path('/app/code/notebooks').rglob('*.ipynb')):
    nb=json.loads(p.read_text())
    hits=[]
    for i,c in enumerate(nb.get('cells', [])):
        src=''.join(c.get('source', []))
        if c.get('cell_type')=='code' and pat.search(src): hits.append((i,src))
    if hits:
        print(f'\n===== {p.relative_to("/app/code")} =====')
        for i,src in hits:
            print(f'--- cell {i} ---\n{src[:6000]}')
